<?php
declare(strict_types=1);namespace App\Http\Controllers\Personnel;use App\Http\Controllers\Controller;use App\Http\Requests\Personnel\EnrollPersonnelFaceRequest;use App\Models\Personnel;use App\Services\Hrd\PersonnelFaceEnrollmentService;use Illuminate\Http\{RedirectResponse,Request};use Symfony\Component\HttpFoundation\BinaryFileResponse;
class PersonnelFaceController extends Controller{public function store(EnrollPersonnelFaceRequest$r,Personnel$personnel,PersonnelFaceEnrollmentService$s):RedirectResponse{$s->enroll($personnel,['front'=>$r->file('front'),'left'=>$r->file('left'),'right'=>$r->file('right')],$r->user());return back()->with('status','Wajah personalia berhasil didaftarkan.');}public function photo(Request$r,Personnel$personnel):BinaryFileResponse{abort_unless($r->user()->can('personnel-face.view'),403);$profile=$personnel->faceProfile;abort_unless($profile,404);return response()->file(storage_path('app/private/'.$profile->primary_reference_photo_path),['Cache-Control'=>'private, no-store']);}public function destroy(Request$r,Personnel$personnel,PersonnelFaceEnrollmentService$s):RedirectResponse{abort_unless($r->user()->can('personnel-face.delete'),403);$s->delete($personnel,$r->user());return back()->with('status','Data wajah personalia berhasil dihapus.');}}
